PLATE_B64 = ''
# 1) Add two podcast microphones on the table of the locked studio plate (SDXL inpainting, only the tabletop is changed).
# 2) Upscale each result x4 with Real-ESRGAN (BSD-3-Clause), export 1920x1080 and 3840x2160.
# Models: diffusers/stable-diffusion-xl-1.0-inpainting-0.1 (CreativeML OpenRAIL++-M), RealESRGAN_x4plus (BSD-3-Clause).
import subprocess, time, io, base64, urllib.request
t0 = time.time()
subprocess.run("pip install -q -U diffusers transformers accelerate spandrel", shell=True, timeout=900)
import torch, numpy as np
from PIL import Image, ImageDraw, ImageFilter
from diffusers import AutoPipelineForInpainting
PLATE = Image.open(io.BytesIO(base64.b64decode(PLATE_B64))).convert("RGB")
W, H = PLATE.size  # 1344 x 768

# mask: the tabletop area only (white = repaint), feathered so the edit blends in
mask = Image.new("L", (W, H), 0)
ImageDraw.Draw(mask).rounded_rectangle([520, 285, 820, 432], radius=24, fill=255)
mask = mask.filter(ImageFilter.GaussianBlur(6))
mask.save("/kaggle/working/mic_mask.png")

pipe = AutoPipelineForInpainting.from_pretrained("diffusers/stable-diffusion-xl-1.0-inpainting-0.1",
        torch_dtype=torch.float16, variant="fp16").to("cuda")
P1 = ("two professional podcast microphones on black boom arm desk stands standing on a round wooden table, "
      "left microphone angled toward the left armchair, right microphone angled toward the right sofa, "
      "headphones lying on the table, small mug")
P2 = "Pixar-style 3D animated movie still, warm cinematic lamp light, dark wood room, soft global illumination, high detail"
NEG = "text, logo, watermark, people, hands, blurry, lowres, deformed, extra tables, lamp"
results = []
for seed in [1, 2, 3, 4]:
    img = pipe(prompt=P1, prompt_2=P2, negative_prompt=NEG, image=PLATE, mask_image=mask, width=W, height=H,
               strength=0.99, num_inference_steps=40, guidance_scale=7.5,
               generator=torch.Generator("cuda").manual_seed(seed)).images[0]
    # keep every pixel outside the mask exactly as in the locked plate
    img = Image.composite(img, PLATE, mask)
    img.save(f"/kaggle/working/mics_seed{seed}.png"); results.append((seed, img))
    print(f"mics seed {seed}: {time.time()-t0:.0f}s", flush=True)
del pipe; torch.cuda.empty_cache()

# Real-ESRGAN x4, tiled
from spandrel import ModelLoader
url = "https://github.com/xinntao/Real-ESRGAN/releases/download/v0.1.0/RealESRGAN_x4plus.pth"
urllib.request.urlretrieve(url, "/kaggle/working/RealESRGAN_x4plus.pth")
model = ModelLoader().load_from_file("/kaggle/working/RealESRGAN_x4plus.pth").cuda().eval().half()
def upscale(im, tile=384, pad=16):
    x = torch.from_numpy(np.asarray(im)).permute(2, 0, 1).float().div(255).unsqueeze(0).cuda().half()
    _, _, h, w = x.shape
    out = torch.zeros((1, 3, h * 4, w * 4), dtype=torch.float16, device="cuda")
    for y0 in range(0, h, tile):
        for x0 in range(0, w, tile):
            ya, yb, xa, xb = max(y0 - pad, 0), min(y0 + tile + pad, h), max(x0 - pad, 0), min(x0 + tile + pad, w)
            with torch.no_grad():
                o = model(x[:, :, ya:yb, xa:xb])
            oy, ox = (y0 - ya) * 4, (x0 - xa) * 4
            th, tw = (min(y0 + tile, h) - y0) * 4, (min(x0 + tile, w) - x0) * 4
            out[:, :, y0 * 4:y0 * 4 + th, x0 * 4:x0 * 4 + tw] = o[:, :, oy:oy + th, ox:ox + tw]
    arr = out.clamp(0, 1).mul(255).byte()[0].permute(1, 2, 0).cpu().numpy()
    return Image.fromarray(arr)
def fit(im, tw, th):  # scale to cover tw x th, then centre-crop (plate is 1.75:1, video is 16:9)
    s = max(tw / im.width, th / im.height); im = im.resize((round(im.width * s), round(im.height * s)), Image.LANCZOS)
    l, t = (im.width - tw) // 2, (im.height - th) // 2
    return im.crop((l, t, l + tw, t + th))
for seed, img in results:
    big = upscale(img)
    fit(big, 3840, 2160).save(f"/kaggle/working/studio_mics_seed{seed}_4k.jpg", quality=93)
    fit(big, 1920, 1080).save(f"/kaggle/working/studio_mics_seed{seed}_1080p.png")
    print(f"upscaled seed {seed}: {time.time()-t0:.0f}s", flush=True)
# comparison sheet: original table zone vs each option, zoomed
crop = (430, 230, 910, 500)
tiles = [("original", PLATE.crop(crop))] + [(f"option {i+1} (seed {s})", im.crop(crop)) for i, (s, im) in enumerate(results)]
tw, th = (crop[2] - crop[0]), (crop[3] - crop[1])
sheet = Image.new("RGB", (tw * 3, (th + 26) * 2), "white"); d = ImageDraw.Draw(sheet)
for k, (name, im) in enumerate(tiles):
    x, y = (k % 3) * tw, (k // 3) * (th + 26); d.text((x + 8, y + 6), name, fill="black"); sheet.paste(im, (x, y + 26))
sheet.save("/kaggle/working/mic_options.jpg", quality=92)
print(f"TOTAL {time.time()-t0:.0f}s")
